-- India customs/trade regulatory requirement register.
-- Seed records are research_pending and must not be treated as legal advice or clearance approval.
create table if not exists public.krim_customs_jurisdiction_requirements (
 id bigint generated by default as identity primary key,
 country_id bigint not null references public.krim_countries(id) on delete restrict,
 requirement_code text not null, requirement_title text not null,
 process_scope text[] not null default array['import','export']::text[],
 cargo_scope text not null default 'all_goods', applicability_rule text not null, operational_control text not null,
 official_authority text not null, source_title text not null,
 source_url text not null check(source_url like 'https://%'), source_reference text,
 source_checked_at timestamptz not null default now(), effective_from date, effective_until date,
 legal_review_status text not null default 'research_pending' check(legal_review_status in ('research_pending','legal_review','verified','superseded','withdrawn')),
 reviewed_by uuid, reviewed_at timestamptz, review_note text, next_review_at timestamptz,
 is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(country_id,requirement_code),
 check(cardinality(process_scope)>0 and process_scope <@ array['import','export','transit','re-export']::text[])
);
create index if not exists krim_customs_jurisdiction_requirements_country_status_idx on public.krim_customs_jurisdiction_requirements(country_id,legal_review_status,is_active);
alter table public.krim_customs_jurisdiction_requirements enable row level security;
alter table public.krim_customs_jurisdiction_requirements force row level security;
revoke all on public.krim_customs_jurisdiction_requirements from public,anon,authenticated;
grant select on public.krim_customs_jurisdiction_requirements to authenticated;
create policy "Customs requirements visible to shipment stakeholders" on public.krim_customs_jurisdiction_requirements for select to authenticated using (
 exists(select 1 from public.krim_shipment_customs c join public.krim_shipments s on s.id=c.shipment_id
 where c.country_id=krim_customs_jurisdiction_requirements.country_id
 and (private.krim_has_permission((select auth.uid()),s.customer_organization_id,'shipment.view')
  or exists(select 1 from public.krim_customs_broker_assignments a where a.customs_record_id=c.id and a.shipment_id=c.shipment_id and a.assignment_status='accepted' and private.krim_has_permission((select auth.uid()),a.broker_organization_id,'compliance.view'))))
 or (coalesce(auth.jwt()->>'aal','aal1')='aal2' and private.krim_has_permission((select auth.uid()),1,'admin.platform'))
);
do $$
declare v_country bigint;
begin
 select id into v_country from public.krim_countries where upper(coalesce(iso2_code,code))='IN' limit 1;
 if v_country is null then raise exception 'India country row not found'; end if;
 insert into public.krim_customs_jurisdiction_requirements
 (country_id,requirement_code,requirement_title,process_scope,cargo_scope,applicability_rule,operational_control,official_authority,source_title,source_url,source_reference,legal_review_status,next_review_at)
 values
 (v_country,'IN_IEC_VALIDITY','Importer Exporter Code (IEC) and annual confirmation',array['import','export'],'goods_trade','Generally required for import/export of goods, subject to exemptions and special cases in the current Foreign Trade Policy and Handbook of Procedures. Verify current IEC status and annual update for the responsible importer/exporter.','Do not mark an importer/exporter trade-ready from GST registration alone. Capture IEC evidence and independently verify status and current-year confirmation or documented exemption.','Directorate General of Foreign Trade (DGFT)','Foreign Trade Policy 2023, Chapter 2, paragraph 2.05','https://content.dgft.gov.in/Website/dgftprod/9158887c-cdfb-4312-92f1-15eeb8e8aa70/%5BUPDATED%5D%20CHAPTER%202%20OF%20FTP.pdf','FTP Chapter 2.05','research_pending',now()+interval '90 days'),
 (v_country,'IN_IMPORT_CORE_DOCUMENTS','Core import declaration and supporting documents',array['import'],'goods_trade','DGFT Chapter 2.06 identifies transport document, commercial invoice-cum-packing list and Bill of Entry as mandatory import documents, with additional requirements depending on goods and applicable law.','Baseline only. Require commodity/HS classification and product-specific LPCO/NOC assessment before any completeness decision; never treat this generic list as clearance approval.','Directorate General of Foreign Trade (DGFT)','Foreign Trade Policy 2023, Chapter 2, paragraph 2.06','https://content.dgft.gov.in/Website/dgftprod/9158887c-cdfb-4312-92f1-15eeb8e8aa70/%5BUPDATED%5D%20CHAPTER%202%20OF%20FTP.pdf','FTP Chapter 2.06(b),(c),(d)','research_pending',now()+interval '90 days'),
 (v_country,'IN_EXPORT_CORE_DOCUMENTS','Core export declaration and supporting documents',array['export'],'goods_trade','DGFT Chapter 2.06 identifies transport document, commercial invoice-cum-packing list and Shipping Bill/Bill of Export as mandatory export documents, with additional requirements depending on goods and applicable law.','Baseline only. Validate export policy status, commodity restrictions, licences and product-specific approvals before any filing readiness determination.','Directorate General of Foreign Trade (DGFT)','Foreign Trade Policy 2023, Chapter 2, paragraph 2.06','https://content.dgft.gov.in/Website/dgftprod/9158887c-cdfb-4312-92f1-15eeb8e8aa70/%5BUPDATED%5D%20CHAPTER%202%20OF%20FTP.pdf','FTP Chapter 2.06(a),(c),(d)','research_pending',now()+interval '90 days'),
 (v_country,'IN_PRODUCT_SPECIFIC_LPCO','Commodity-specific restrictions, licences, permits, certificates and NOCs',array['import','export'],'commodity_dependent','Requirements depend on tariff item, product description, end-use, origin/destination, applicable policy conditions and participating government agency controls.','No generic automated approval. Require HS code, detailed commodity attributes, origin/destination and current official commodity-wise compliance check; unresolved PGA/LPCO applicability blocks release readiness.','ICEGATE / CBIC and relevant Participating Government Agencies','ICEGATE Compliance Information Portal (CIP)','https://cip.icegate.gov.in/','Commodity-wise procedures, agency links, duties and taxes','research_pending',now()+interval '30 days'),
 (v_country,'IN_ICEGATE_ACCESS_AND_FILING','ICEGATE registration and electronic customs filing pathway',array['import','export'],'goods_trade','ICEGATE registration facilitates customs-related electronic interactions and filing; required account/role depends on stakeholder and transaction.','KRIM must not file or impersonate an importer, exporter or licensed customs broker. Future integration requires correct authorized stakeholder identity and documented authorization.','Central Board of Indirect Taxes and Customs (CBIC) / ICEGATE','ICEGATE Registration FAQ and official portal','https://www.icegate.gov.in/','ICEGATE registration and electronic filing information','research_pending',now()+interval '90 days')
 on conflict(country_id,requirement_code) do update set requirement_title=excluded.requirement_title,process_scope=excluded.process_scope,cargo_scope=excluded.cargo_scope,applicability_rule=excluded.applicability_rule,operational_control=excluded.operational_control,official_authority=excluded.official_authority,source_title=excluded.source_title,source_url=excluded.source_url,source_reference=excluded.source_reference,source_checked_at=now(),legal_review_status='research_pending',reviewed_by=null,reviewed_at=null,review_note=null,next_review_at=excluded.next_review_at,updated_at=now();
end $$;